-- Incident type classifier (FR12, plan 10.4): each crowd report is tagged
-- with an incident type from its description before DBSCAN looks at it
-- (thesis Process 2.0). TF-IDF over word unigrams and bigrams, then
-- multinomial logistic regression over the four types. The model is trained
-- and exported by ml/classifier/train_classifier.py; `IncidentClassifier` in
-- packages/shared runs the same arithmetic.
--
-- The v1-sample model at the end of this file is trained on made-up sample
-- descriptions, not MDRRMD records. Load the real one with a new migration
-- that inserts it and makes it the active model.

create table public.classifier_model (
  model_id text primary key,
  is_active boolean not null default false,
  note text,
  -- The types in the order the model scores them.
  labels text[] not null,
  intercept double precision[] not null,
  -- Below this a report is left untagged (the resident's own choice, if
  -- any, is then used for the cluster).
  min_confidence double precision not null check (min_confidence between 0 and 1),
  -- {"term": [idf, one weight per label]}
  terms jsonb not null check (jsonb_typeof(terms) = 'object'),
  loaded_at timestamptz not null default now(),
  check (labels <@ array['flood', 'fire', 'medical', 'structural']),
  check (cardinality(labels) >= 2 and cardinality(intercept) = cardinality(labels))
);
comment on table public.classifier_model is 'Exported TF-IDF + logistic regression models for crowd report types (FR12); one is active.';
create unique index classifier_model_one_active on public.classifier_model ((true)) where is_active;

alter table public.classifier_model enable row level security;
revoke all on public.classifier_model from anon, authenticated;
create policy "classifier models: dispatchers and admins" on public.classifier_model
  for select to authenticated using ((select private.is_dispatcher()));
grant select on public.classifier_model to authenticated;

-- The most likely type for a description, its probability, and whether
-- that reaches the model's minimum. No row when no model is active.
create function private.classify_report(p_text text)
returns table (category text, confidence double precision, sure boolean)
language sql stable security definer set search_path = ''
as $$
  with m as (
    select labels, intercept, min_confidence, terms
      from public.classifier_model
     where is_active
  ), tok as (
    -- A word is two or more letters or digits; everything else separates.
    select r.w[1] as t, r.n
      from regexp_matches(
             replace(lower(coalesce(p_text, '')), 'Ñ', 'ñ'), '[a-zñ0-9]{2,}', 'g'
           ) with ordinality as r(w, n)
  ), grams as (
    select t as g from tok
    union all
    select p.t || ' ' || p.nxt
      from (select t, lead(t) over (order by n) as nxt from tok) p
     where p.nxt is not null
  ), tf as (
    select g, count(*)::double precision as n from grams group by g
  ), feat as (
    -- tf x idf for each known term, with its weights.
    select tf.n * (m.terms -> tf.g ->> 0)::double precision as x, m.terms -> tf.g as w
      from tf cross join m
     where m.terms ? tf.g
  ), score as (
    -- The vector is scaled to length 1, as in training. With no known
    -- term the scores are the intercepts alone.
    select l.i, l.label, m.min_confidence,
           m.intercept[l.i] + coalesce(
             (select sum(f.x * (f.w ->> l.i::int)::double precision) from feat f)
             / nullif((select sqrt(sum(f.x * f.x)) from feat f), 0), 0) as s
      from m cross join lateral unnest(m.labels) with ordinality as l(label, i)
  ), e as (
    select i, label, min_confidence, exp(s - (select max(s) from score)) as v from score
  )
  select e.label,
         e.v / (select sum(v) from e),
         e.v / (select sum(v) from e) >= e.min_confidence
    from e
   order by e.v desc, e.i
   limit 1
$$;

-- Tags a new report unless it already carries a tag. The resident's own
-- choice (reported_type) is kept as it is.
create function private.tag_crowd_report()
returns trigger
language plpgsql security definer set search_path = ''
as $$
declare
  c record;
begin
  if new.category is null then
    select * into c from private.classify_report(new.description);
    if found and c.sure then
      new.category := c.category;
      new.category_confidence := round(c.confidence::numeric, 4);
    end if;
  end if;
  return new;
end $$;

create trigger crowd_report_tag
  before insert on public.crowd_report
  for each row execute function private.tag_crowd_report();

revoke execute on function private.classify_report(text), private.tag_crowd_report()
from public, anon, authenticated;

